// Deterministic workspace-change sanitizer & boundary gate for non-shell / programmatic hosted callers.
// Enforces the same repository-boundary, secret-path, secret-content, redaction, and byte-limit rules
// as scripts/collect.mjs so hosted uploads never rely on model-side filtering.
import { lstatSync, realpathSync } from 'node:fs';
import path from 'node:path';
import { secretPath, secretContent, safeRead, redactSecrets } from './safety.mjs';

const LOCK_NAMES = new Set([
  'package-lock.json', 'npm-shrinkwrap.json', 'yarn.lock', 'pnpm-lock.yaml', 'bun.lockb', 'bun.lock',
  'Cargo.lock', 'poetry.lock', 'Pipfile.lock', 'uv.lock', 'go.sum', 'composer.lock', 'Gemfile.lock',
  'Podfile.lock', 'mix.lock', 'pubspec.lock', 'flake.lock', 'gradle.lockfile', 'packages.lock.json', 'deno.lock',
]);
const VENDOR_RE = /(^|\/)(node_modules|vendor|vendors|third_party|dist|build|out|target|\.next|\.nuxt|__pycache__|\.venv|venv|coverage|\.gradle|Pods)\//;
const GENERATED_NAME_RE = /(\.min\.(js|css)|\.map|\.pb\.go|_pb2(_grpc)?\.py|\.pb\.(h|cc)|\.generated\.\w+|_generated\.\w+|\.gen\.\w+|\.snap|\.svg|\.ipynb)$|(^|\/)(__generated__|generated)\//;
const BINARY_EXT_RE = /\.(png|jpe?g|gif|webp|ico|bmp|tiff?|pdf|zip|gz|tgz|bz2|xz|7z|rar|jar|war|class|so|dylib|dll|exe|bin|o|a|wasm|woff2?|ttf|otf|eot|mp[34]|mov|avi|webm|ogg|wav|sqlite3?|db|pyc|psd|ai|keystore)$/i;

const DEFAULT_MAX_BYTES = 90_000;
const HARD_MAX_BYTES = 700_000;
const bytes = (s) => Buffer.byteLength(s, 'utf8');

function normalizeRelPath(raw) {
  if (typeof raw !== 'string' || !raw.trim()) return { rel: null, why: 'empty path' };
  if (raw.includes('\0') || /[\r\n]/.test(raw)) return { rel: null, why: 'invalid control character in path' };
  const posix = raw.replace(/\\/g, '/');
  if (posix.startsWith('/') || /^[A-Za-z]:/.test(posix)) return { rel: null, why: 'outside the workspace (absolute path)' };
  const norm = path.posix.normalize(posix).replace(/^\.\//, '');
  if (!norm || norm === '.' || norm === '..' || norm.startsWith('../')) {
    return { rel: null, why: 'outside the workspace (path traversal)' };
  }
  return { rel: norm, why: null };
}

function checkWorkspaceBoundary(realRoot, rel) {
  const full = path.resolve(realRoot, rel);
  if (full !== realRoot && !full.startsWith(realRoot + path.sep)) return 'outside the workspace';
  // Walk existing components to ensure no symlink component escapes or redirects the path.
  const parts = rel.split('/');
  let cur = realRoot;
  for (const part of parts) {
    cur = path.join(cur, part);
    let st;
    try { st = lstatSync(cur); } catch (e) { if (e.code === 'ENOENT') return null; return 'unreadable'; }
    if (st.isSymbolicLink()) return 'symlink (outside or redirected workspace path)';
  }
  try {
    const real = realpathSync(full);
    if (real !== realRoot && !real.startsWith(realRoot + path.sep)) return 'outside the workspace';
  } catch (e) {
    if (e.code !== 'ENOENT') return 'unreadable';
  }
  return null;
}

function skipReason(rel, buf) {
  const base = path.posix.basename(rel);
  if (secretPath(rel)) return 'secret-looking file';
  if (LOCK_NAMES.has(base) || /\.lock$/.test(base)) return 'lockfile';
  if (VENDOR_RE.test(rel)) return 'vendored/build output';
  if (GENERATED_NAME_RE.test(rel)) return 'generated/binary-like';
  if (BINARY_EXT_RE.test(rel)) return 'binary';
  if (buf) {
    if (buf.subarray(0, 8000).includes(0)) return 'binary';
    const head = buf.subarray(0, 600).toString('utf8');
    if (/(@generated|DO NOT EDIT|auto-?generated|autogenerated|Code generated by)/i.test(head)) return 'generated';
    const sc = secretContent(buf.toString('utf8'), rel);
    if (sc) return `secret-looking content (${sc})`;
  }
  return null;
}

/**
 * Deterministically validates, bounds, and sanitizes workspace diffs and files before hosted upload.
 * Intended for hosts/tools without shell access to `scripts/collect.mjs`.
 * Fails closed (`{ ok: false, stop: true }`) when nothing reviewable remains or workspace root is invalid.
 */
export function buildGuardedWorkspaceBundle({
  root,
  diffSections = [],
  files = [],
  maxBytes = DEFAULT_MAX_BYTES,
} = {}) {
  let realRoot;
  try {
    realRoot = realpathSync(path.resolve(root || ''));
  } catch {
    return { ok: false, stop: true, reason: 'workspace root does not exist', bundle: '', bundleBytes: 0, excluded: [], redactions: [] };
  }
  const cap = Math.min(Math.max(Number(maxBytes) || DEFAULT_MAX_BYTES, 2000), HARD_MAX_BYTES);
  const excluded = [];
  const redactions = [];
  const recordRedaction = (file, count) => {
    if (!count) return;
    const hit = redactions.find((x) => x.path === file);
    if (hit) hit.count += count;
    else redactions.push({ path: file, count });
  };

  const keptDiffs = [];
  for (const sec of diffSections) {
    const rawPath = sec?.path;
    const rawDiff = typeof sec?.diff === 'string' ? sec.diff : '';
    const { rel, why: pathWhy } = normalizeRelPath(rawPath);
    if (!rel) {
      excluded.push({ path: String(rawPath ?? '(missing)'), reason: `diff, ${pathWhy}` });
      continue;
    }
    const boundWhy = checkWorkspaceBoundary(realRoot, rel);
    if (boundWhy) {
      excluded.push({ path: rel, reason: `diff, ${boundWhy}` });
      continue;
    }
    const isBinaryDiff = /^Binary files |^GIT binary patch/m.test(rawDiff);
    const sc = secretContent(rawDiff, rel);
    const why = skipReason(rel, null) || (isBinaryDiff ? 'binary' : null) || (sc ? `secret-looking content (${sc})` : null);
    if (why) {
      excluded.push({ path: rel, reason: `diff, ${why} (diff omitted)` });
      continue;
    }
    const red = redactSecrets(rawDiff, rel, { diff: true });
    recordRedaction(rel, red.count);
    keptDiffs.push({ path: rel, text: red.text.endsWith('\n') ? red.text : `${red.text}\n` });
  }

  const keptFiles = [];
  for (const rawPath of files) {
    const { rel, why: pathWhy } = normalizeRelPath(rawPath);
    if (!rel) {
      excluded.push({ path: String(rawPath ?? '(missing)'), reason: `file, ${pathWhy}` });
      continue;
    }
    const boundWhy = checkWorkspaceBoundary(realRoot, rel);
    if (boundWhy) {
      excluded.push({ path: rel, reason: `file, ${boundWhy}` });
      continue;
    }
    const { buf, why: readWhy } = safeRead(realRoot, rel);
    if (!buf) {
      excluded.push({ path: rel, reason: `file, ${readWhy}` });
      continue;
    }
    const why = skipReason(rel, buf);
    if (why) {
      excluded.push({ path: rel, reason: `file, ${why}` });
      continue;
    }
    const red = redactSecrets(buf.toString('utf8'), rel);
    recordRedaction(rel, red.count);
    keptFiles.push({ path: rel, text: red.text });
  }

  // Assemble strictly within `cap` bytes.
  const parts = [];
  let used = 0;
  let diffIncluded = 0;
  const truncated = [];

  if (keptDiffs.length > 0) {
    const diffBudget = Math.floor(cap * 0.45);
    const header = '=== DIFF ===\n';
    let diffOut = header;
    for (const d of keptDiffs) {
      if (bytes(diffOut) + bytes(d.text) <= diffBudget) {
        diffOut += d.text;
        diffIncluded++;
      } else {
        const note = `[... diff for ${d.path} truncated by MegaLens guard ...]\n`;
        const room = diffBudget - bytes(diffOut) - bytes(note);
        if (room >= 120) {
          let cut = Buffer.from(d.text).subarray(0, room).toString('utf8');
          const nl = cut.lastIndexOf('\n');
          if (nl > 0) cut = cut.slice(0, nl + 1);
          diffOut += cut + note;
          diffIncluded++;
        }
        truncated.push(d.path);
      }
    }
    if (diffIncluded > 0) {
      parts.push(diffOut);
      used += bytes(diffOut);
    }
  }

  let filesIncluded = 0;
  for (const f of keptFiles) {
    const block = `=== FILE: ${f.path} ===\n${f.text}\n`;
    const sep = parts.length ? 1 : 0;
    if (used + sep + bytes(block) <= cap) {
      parts.push(block);
      used += sep + bytes(block);
      filesIncluded++;
    } else {
      truncated.push(f.path);
    }
  }

  if (diffIncluded === 0 && filesIncluded === 0) {
    const reason = excluded.length
      ? excluded.map((e) => `${e.path}: ${e.reason}`).join('; ')
      : 'no reviewable workspace changes remained';
    return {
      ok: false,
      stop: true,
      reason,
      bundle: '',
      bundleBytes: 0,
      excluded,
      redactions,
      truncated,
    };
  }

  const bundle = parts.join('\n');
  const bundleBytes = bytes(bundle);
  return {
    ok: true,
    stop: false,
    reason: null,
    bundle,
    bundleBytes,
    excluded,
    redactions,
    truncated,
  };
}
